export function terrainHeight(kind,u,v,variation=0){const g=(x,y,sx,sy,a)=>a*Math.exp(-((u-x)**2/sx+(v-y)**2/sy));let z;
switch(kind){case 'flat':z=10;break;case 'slope':z=3+20*v+3*u;break;case 'basin':z=3+22*(1-Math.exp(-((u-.5)**2+(v-.5)**2)*6));break;case 'ridge':z=4+g(.5,.5,.012,.45,24)+g(.72,.7,.025,.025,7);break;case 'valley':z=4+25*(u-.5-.12*Math.sin(v*7))**2*3+5*v;break;case 'terraces':z=3+Math.floor(v*5)*4+u*3;break;case 'crater':{let r=Math.hypot(u-.5,v-.5);z=3+24*Math.exp(-(((r-.27)/.085)**2));break}case 'coast':z=1+20/(1+Math.exp(-(u-.4-.07*Math.sin(v*10))*18))+4*v;break;case 'dunes':z=5+7*(Math.sin(u*16+v*5)+1)*(.5+.5*Math.sin(v*3)**2)+2*v;break;case 'saddle':z=5+g(.25,.5,.035,.15,22)+g(.75,.5,.035,.15,22);break;default:z=2+g(.32,.64,.047,.09,22)+g(.75,.34,.045,.05,14)+2*v}
return z+variation*(Math.sin(u*13+v*4)*Math.cos(v*11-u*3)+.45*Math.sin(u*27-v*17))}
export function closestSegment(p,a,b){let dx=b[0]-a[0],dy=b[1]-a[1],t=Math.max(0,Math.min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/(dx*dx+dy*dy||1))),q=[a[0]+t*dx,a[1]+t*dy];return{distance:Math.hypot(p[0]-q[0],p[1]-q[1]),point:q}}
export function translated(points,dx,dy,w,h){let xs=points.map(p=>p[0]),ys=points.map(p=>p[1]);dx=Math.max(-Math.min(...xs),Math.min(w-Math.max(...xs),dx));dy=Math.max(-Math.min(...ys),Math.min(h-Math.max(...ys),dy));return points.map(p=>[p[0]+dx,p[1]+dy])}
export function joinContours(levels,w,h){let out=[],tol=Math.max(w,h)*1e-7,key=p=>p.map(v=>Math.round(v/tol)).join(',');for(let level of levels){const links=new Map(),segs=level.segs,used=new Set();segs.forEach((s,i)=>s.forEach(p=>{let k=key(p);if(!links.has(k))links.set(k,[]);links.get(k).push(i)}));function walk(start,id){let ps=[start],p=start,k=id;while(k!==undefined&&!used.has(k)){used.add(k);let seg=segs[k],q=key(seg[0])===key(p)?seg[1]:seg[0];ps.push(q);p=q;k=(links.get(key(q))||[]).find(i=>!used.has(i))}return ps}const starts=[...segs.keys()].sort((a,b)=>{const endpoint=i=>segs[i].some(p=>links.get(key(p)).length===1)?0:1;return endpoint(a)-endpoint(b)});for(let id of starts){if(used.has(id))continue;let seg=segs[id],start=seg.find(p=>links.get(key(p)).length===1)||seg[0],ps=walk(start,id),closed=ps.length>2&&key(ps[0])===key(ps.at(-1));if(closed)ps.pop();if(ps.length<(closed?3:2))continue;let step=Math.max(1,Math.ceil(ps.length/100)),points=ps.filter((_,i)=>i%step===0);if(!closed&&points.at(-1)!==ps.at(-1))points.push(ps.at(-1));if(points.length>=(closed?3:2))out.push({z:level.z,points:points.map(p=>p.slice()),closed,visible:true,locked:false,enabled:true,name:`地形等高線 ${level.z} m`,color:level.major?'#9858a3':'#559897'})}}return out}
